def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def compute_sequence_and_factorize(N):
    a = [0] * (N + 1)
    a[1] = 10

    all_factors = {}

    # Calculate a2 to aN
    for n in range(1, N):
        # a_{n+1} = 6a_n - 2^{n+2} - 3^{n+1} + 5
        a_next = 6 * a[n] - (2**(n+2)) - (3**(n+1)) + 5
        a[n+1] = a_next

        # Factorize a_{n+1}
        factors = prime_factorization(a_next)
        for p in factors:
            all_factors[p] = True

    return a[1:N+1], all_factors.keys()

N = 6
sequence, prime_factors = compute_sequence_and_factorize(N)

print(f"Sequence (a1 to a6): {sequence}")
print(f"Unique Prime Factors found: {sorted(list(prime_factors))}")

# Detailed factorization for recording
detailed_results = []
for i in range(N):
    term = sequence[i]
    factors = prime_factorization(term)
    factor_str = " * ".join([f"{p}^{e}" for p, e in factors.items()])
    detailed_results.append(f"a_{i+1} = {term} = {factor_str}")

print("\n--- Detailed Factorization ---")
for result in detailed_results:
    print(result)

